from typing import List

class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        seen = {}  # Maps each number to the index where it was first seen

        for i, x in enumerate(nums):
            needed = target - x
            if needed in seen:
                return [seen[needed], i]

            seen[x] = i
```

For each value `x`, the loop checks whether its partner, `target - x`, was already seen. If so, it returns both indices. Otherwise, it saves `x` and its index for a later check. Checking before storing also lets two equal values at different indices form a pair.

